package com.smartcanteen.controller;
import com.razorpay.RazorpayClient;
import com.razorpay.RazorpayException;
import com.razorpay.Utils;
import com.razorpay.Order;
import com.smartcanteen.entity.CustomerOrder;
import com.smartcanteen.entity.OrderStatus;
import com.smartcanteen.entity.PaymentStatus;
import com.smartcanteen.repository.*;import com.smartcanteen.service.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import jakarta.servlet.http.HttpServletRequest;import org.json.JSONObject;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
import com.smartcanteen.entity.Payment;
import com.razorpay.RazorpayClient;
@RestController @RequestMapping("/api/payments/razorpay") public class PaymentController {
 private final OrderRepository orders;private final PaymentRepository payments;private final CurrentUser current;private final String keyId,keySecret,webhookSecret;
 public PaymentController(OrderRepository o,PaymentRepository p,CurrentUser c,@Value("${razorpay.key-id}")String k,@Value("${razorpay.key-secret}")String s,@Value("${razorpay.webhook-secret}")String w){orders=o;payments=p;current=c;keyId=k;keySecret=s;webhookSecret=w;}
 public record CreateRequest(@NotNull Long orderId){} public record VerifyRequest(@NotBlank String razorpayOrderId,@NotBlank String razorpayPaymentId,@NotBlank String razorpaySignature){}
 @PostMapping("/create-order") @Transactional public Map<String,Object> create(@Valid @RequestBody CreateRequest r)throws RazorpayException{CustomerOrder o=orders.findByIdAndUserId(r.orderId(),current.get().getId()).orElseThrow(()->new IllegalArgumentException("Order not found."));if(o.getPaymentStatus()==PaymentStatus.PAID)throw new IllegalArgumentException("Order already paid.");if(keyId.isBlank()||keySecret.isBlank())throw new IllegalArgumentException("Configure Razorpay test keys on the backend first.");int paise=o.getTotalAmount().multiply(java.math.BigDecimal.valueOf(100)).intValueExact();JSONObject req=new JSONObject();req.put("amount",paise);req.put("currency","INR");req.put("receipt",o.getOrderNumber());Order rzOrder=new RazorpayClient(keyId,keySecret).orders.create(req);Payment p=payments.findByOrderId(o.getId()).orElseGet(Payment::new);p.setOrder(o);p.setProviderOrderId(rzOrder.get("id"));p.setAmount(o.getTotalAmount());p.setPaymentStatus(PaymentStatus.PENDING);payments.save(p);o.setPaymentStatus(PaymentStatus.PENDING);orders.save(o);return Map.of("keyId",keyId,"razorpayOrderId",rzOrder.get("id"),"amount",paise,"currency","INR","appOrderId",o.getId(),"orderNumber",o.getOrderNumber());}
 @PostMapping("/verify") @Transactional public Map<String,String> verify(@Valid @RequestBody VerifyRequest r)throws RazorpayException{Payment p=payments.findByProviderOrderId(r.razorpayOrderId()).orElseThrow(()->new IllegalArgumentException("Payment order not found."));if(!p.getOrder().getUser().getId().equals(current.get().getId()))throw new IllegalArgumentException("Payment does not belong to this user.");if(p.getPaymentStatus()==PaymentStatus.PAID)return Map.of("status","PAID","message","Payment already verified.");if(!constant(signature(r.razorpayOrderId()+"|"+r.razorpayPaymentId(),keySecret),r.razorpaySignature()))throw new IllegalArgumentException("Payment signature verification failed.");var remote=new RazorpayClient(keyId,keySecret).payments.fetch(r.razorpayPaymentId());if(!r.razorpayOrderId().equals(remote.get("order_id"))||!"captured".equalsIgnoreCase(String.valueOf(remote.get("status"))))throw new IllegalArgumentException("Payment is not captured for this order.");p.setProviderPaymentId(r.razorpayPaymentId());p.setSignatureVerified(true);p.setPaymentStatus(PaymentStatus.PAID);p.getOrder().setPaymentStatus(PaymentStatus.PAID);p.getOrder().setOrderStatus(OrderStatus.PAYMENT_CONFIRMED);payments.save(p);orders.save(p.getOrder());return Map.of("status","PAID","message","Payment verified. Collect your order at the canteen counter.");}
 @PostMapping("/webhook") @Transactional public ResponseEntity<?> webhook(HttpServletRequest request,@RequestHeader(value="X-Razorpay-Signature",required=false)String sig)throws Exception{String body=new String(request.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(webhookSecret.isBlank()||sig==null||!constant(signature(body,webhookSecret),sig))return ResponseEntity.badRequest().body(Map.of("message","Invalid webhook signature."));JSONObject event=new JSONObject(body);if("payment.captured".equals(event.optString("event"))){JSONObject e=event.getJSONObject("payload").getJSONObject("payment").getJSONObject("entity");payments.findByProviderOrderId(e.optString("order_id")).ifPresent(p->{if(p.getPaymentStatus()!=PaymentStatus.PAID){p.setProviderPaymentId(e.optString("id"));p.setPaymentStatus(PaymentStatus.PAID);p.setSignatureVerified(true);p.getOrder().setPaymentStatus(PaymentStatus.PAID);p.getOrder().setOrderStatus(OrderStatus.PAYMENT_CONFIRMED);payments.save(p);orders.save(p.getOrder());}});}return ResponseEntity.ok(Map.of("received",true));}
 private static String signature(String text,String secret){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(text.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("Signature computation failed.");}}
 private static boolean constant(String a,String b){return a!=null&&b!=null&&MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}
}
